import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { FiEdit3 } from "react-icons/fi";
import DashboardLayout from "../../layouts/DashboardLayout";
import Card from "../../components/Card";
import FormField from "../../components/FormField";
import { registrationApi } from "../../api/registrationApi";
import { studentApi } from "../../api/studentApi";
import { courseApi } from "../../api/courseApi";
import { useLookupOptions } from "../../hooks/useLookupOptions";
import { useToast } from "../../context/ToastContext";
import { extractErrorMessage } from "../../api/axios";
import { validateFields, isRequired } from "../../utils/validators";
import { fullName } from "../../utils/formatters";

const SEMESTER_OPTIONS = [
  { value: "Semester I", label: "Semester I" },
  { value: "Semester II", label: "Semester II" },
  { value: "Summer", label: "Summer" }
];

const initialValues = { student_id: "", course_id: "", semester: "", academic_year: "" };

export default function RegisterStudent() {
  const navigate = useNavigate();
  const toast = useToast();

  const [values, setValues] = useState(initialValues);
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const { options: studentOptions, isLoading: loadingStudents } = useLookupOptions(
    studentApi.getAll,
    (s) => ({ value: s.id, label: `${fullName(s)} — ${s.registration_number}` })
  );
  const { options: courseOptions, isLoading: loadingCourses } = useLookupOptions(
    courseApi.getAll,
    (c) => ({ value: c.id, label: `${c.code} — ${c.name}` })
  );

  function handleChange(e) {
    const { name, value } = e.target;
    setValues((prev) => ({ ...prev, [name]: value }));
    setErrors((prev) => ({ ...prev, [name]: "" }));
  }

  async function handleSubmit(e) {
    e.preventDefault();
    const fieldErrors = validateFields(values, {
      student_id: [isRequired],
      course_id: [isRequired],
      semester: [isRequired],
      academic_year: [isRequired]
    });
    if (Object.keys(fieldErrors).length > 0) {
      setErrors(fieldErrors);
      return;
    }

    setIsSubmitting(true);
    try {
      await registrationApi.create(values);
      toast.success("Registration successful");
      navigate(`/registrations/student/${values.student_id}`);
    } catch (err) {
      toast.error(extractErrorMessage(err, "Unable to register this course."));
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <DashboardLayout>
      <div className="max-w-lg mx-auto">
        <div className="flex items-center gap-2 mb-6">
          <div className="h-9 w-9 rounded-lg bg-navy-100 text-navy-700 flex items-center justify-center">
            <FiEdit3 size={16} />
          </div>
          <h1 className="font-display text-xl text-navy-800">Register Student</h1>
        </div>

        <Card className="p-6">
          <form onSubmit={handleSubmit} className="space-y-4" noValidate>
            <FormField
              as="select"
              label="Select Student"
              name="student_id"
              value={values.student_id}
              onChange={handleChange}
              error={errors.student_id}
              required
              options={studentOptions}
              placeholder={loadingStudents ? "Loading students..." : "Select a student"}
            />
            <FormField
              as="select"
              label="Select Course"
              name="course_id"
              value={values.course_id}
              onChange={handleChange}
              error={errors.course_id}
              required
              options={courseOptions}
              placeholder={loadingCourses ? "Loading courses..." : "Select a course"}
            />
            <div className="grid sm:grid-cols-2 gap-4">
              <FormField
                as="select"
                label="Semester"
                name="semester"
                value={values.semester}
                onChange={handleChange}
                error={errors.semester}
                required
                options={SEMESTER_OPTIONS}
                placeholder="Select semester"
              />
              <FormField
                label="Academic Year"
                name="academic_year"
                value={values.academic_year}
                onChange={handleChange}
                error={errors.academic_year}
                required
                placeholder="e.g. 2025/2026"
              />
            </div>
            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full py-2.5 rounded-lg text-sm bg-navy-700 text-white hover:bg-navy-800 transition disabled:opacity-60"
            >
              {isSubmitting ? "Registering..." : "Register Course"}
            </button>
          </form>
        </Card>
      </div>
    </DashboardLayout>
  );
}
